from pathlib import Path
import sys,json,hashlib
import numpy as np
from scipy.stats import binomtest
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
CODE=Path(__file__).parent;ROOT=CODE.parent;RUN=Path(sys.argv[1]);load=lambda p:json.loads(Path(p).read_text())
subjects=['reference','baseline','waypoints','planner_oracle','planner_estimated','policy_true_pose'];titles=['Checkpoint anterior','Piloto direto','Piloto alvos intermediários','Planejador + pose verdadeira','Planejador + pose estimada','Política + pose verdadeira']
results={s:load(RUN/f'eval_full_{s}/summary.json') for s in subjects}
rows={s:load(RUN/f'eval_full_{s}/episodes.json') for s in subjects}
ref={r['seed']:r for r in rows['reference']}
for subject in subjects:
 assert all(r['fingerprint']==ref[r['seed']]['fingerprint'] for r in rows[subject]),subject
bench=load(RUN/'benchmarks.json');native=load(RUN/'native_benchmarks.json');recommend=load(RUN/'recommended_configuration.json');services=load(CODE/'service_resolution.json');optimization=load(RUN/'validation/optimization.json');native_validation=load(CODE/'native_validation.json');sampler=load(CODE/'sampler_validation.json');scenarios=load(RUN/'scenario_manifest.json');coverage=scenarios['coverage']
def ci(k,n):
 z=1.96;p=k/n;d=1+z*z/n;c=(p+z*z/(2*n))/d;h=z*np.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return [float(c-h),float(c+h)]
paired={};rng=np.random.default_rng(99)
for s in subjects[1:]:
 delta=np.array([int(r['success'])-int(ref[r['seed']]['success']) for r in rows[s]])
 gains=int(np.sum(delta==1));losses=int(np.sum(delta==-1));bootstrap=delta[rng.integers(100,size=(10000,100))].mean(1)
 paired[s]=dict(change=float(delta.mean()),ci95=np.quantile(bootstrap,[.025,.975]).tolist(),gains=gains,losses=losses,p=binomtest(gains,gains+losses).pvalue if gains+losses else 1.)
for s in subjects:results[s]['success_ci95']=ci(round(results[s]['success']*100),100)
# Independent larger-coverage suite, same new scenarios for both compatible policies.
wide={s:load(RUN/f'eval_coverage_{s}/summary.json') for s in ['reference','baseline']}
a=load(RUN/'eval_coverage_reference/episodes.json');b=load(RUN/'eval_coverage_baseline/episodes.json');assert [r['fingerprint'] for r in a]==[r['fingerprint'] for r in b]
(RUN/'analysis.json').write_text(json.dumps(dict(full=results,paired=paired,coverage_evaluation=wide),indent=2))
fig,axes=plt.subplots(1,2,figsize=(13,5));x=np.arange(3)
axes[0].bar(x-.18,[r['transitions_s'] for r in bench],.36,label='Python otimizado');axes[0].bar(x+.18,[r['transitions_s'] for r in native],.36,label='LiDAR nativo equivalente');axes[0].set_xticks(x,['1 ambiente','2 ambientes','4 ambientes']);axes[0].set(ylabel='Transições por segundo',title='Coleta + atualizações PPO (4.096 transições)');axes[0].legend()
x=np.arange(len(subjects));axes[1].bar(x-.18,[results[s]['success'] for s in subjects],.36,label='Sucesso');axes[1].bar(x+.18,[results[s]['collision'] for s in subjects],.36,label='Colisão');axes[1].set_xticks(x,['Anterior','Piloto A','Piloto B','Planner\nverdade','Planner\nestimativa','Política\nverdade'],rotation=15);axes[1].set(ylim=(0,1.05),title='Mesmos 100 cenários do conjunto inicial');axes[1].legend();fig.tight_layout();fig.savefig(RUN/'resultados.png',dpi=170);plt.close(fig)
# Spatial coverage and source footprints are the same static occupancy.
from PIL import Image
import yaml
cfg=yaml.safe_load((ROOT/'assets/arenas/arena_2016_v2/layout_review.yaml').read_text());w,h=cfg['floor']['size_m'];image=np.array(Image.open(ROOT/'assets/arenas/arena_2016_v2/review/colisao_fisica.pgm'))
fig,axes=plt.subplots(1,2,figsize=(11,7))
for ax in axes:ax.imshow(image,extent=[0,w,0,h],cmap='gray',vmin=0,vmax=254);ax.set_aspect('equal');ax.set(xlabel='x (m)',ylabel='y (m)')
points=np.array([r['start'] for r in scenarios['scenarios'] if r['suite']=='full']);axes[0].scatter(points[:,0],points[:,1],s=8,c='#1769aa');axes[0].set_title('100 inícios — amostrador antigo por disco')
points=np.load(CODE/'sampler_starts.npy')[:100];axes[1].scatter(points[:,0],points[:,1],s=5,c='#13804b');axes[1].set_title('100 inícios — footprint orientado (500 resets validados)');fig.tight_layout();fig.savefig(RUN/'cobertura.png',dpi=170);plt.close(fig)
# Results by straight-line distance, so sampling restrictions remain visible.
by_distance={}
for subject in subjects:
 by_distance[subject]={}
 for label,lo,hi in [('ate_2m',0,2),('2_a_4m',2,4),('mais_4m',4,100)]:
  group=[r for r in rows[subject] if lo<r['initial_distance']<=hi]
  by_distance[subject][label]=dict(n=len(group),success=sum(r['success'] for r in group),collision=sum(r['collision'] for r in group))
(RUN/'by_distance.json').write_text(json.dumps(by_distance,indent=2))
# Re-check frozen assets/checkpoints after every diagnostic.
before=load(RUN/'preservation_before.json');changed=[name for name,digest in before.items() if hashlib.sha256((ROOT/name).read_bytes()).hexdigest()!=digest];assert not changed
(RUN/'preservation_final.json').write_text(json.dumps(dict(checked=len(before),changed=changed,preserved=True),indent=2))
lines=['# Desenvolvimento da IA — experimentos v2','', '## Decisão','', 'A infraestrutura ficou mais rápida, mas os pilotos não demonstraram aprendizado suficiente para liberar um treinamento longo. O próximo ciclo deve corrigir localização e representação da navegação, usando o planejador como referência/possível professor. Os modelos anteriores permanecem preservados.','', '## Velocidade medida','', '| Ambientes | Python otimizado, passos/s | LiDAR nativo, passos/s |','|---|---:|---:|']
for a,b in zip(bench,native):lines.append(f"| {a['n_envs']} | {a['transitions_s']:.1f} | {b['transitions_s']:.1f} |")
ratio=recommend['measured_transitions_s']/bench[0]['transitions_s'];lines += ['',f"Recomendação: **{recommend['n_envs']} ambientes e LiDAR nativo**, com uma thread Torch e rollout global de 512 transições (256/ambiente). Medição: {recommend['measured_transitions_s']:.1f} passos/s, **{(ratio-1)*100:.0f}% acima** do teste inicial com um ambiente. Quatro ambientes nativos atingiram {native[-1]['transitions_s']:.1f}, apenas {100*(native[-1]['transitions_s']/native[1]['transitions_s']-1):.1f}% acima de dois; não compensa adotar mais processos como padrão.",'','Os testes medem tempo de coleta mais treinamento PPO, excluindo inicialização de processos/modelos. Cada configuração realizou 4.096 transições, com mesmo checkpoint, semente e tamanho global de rollout. São medições curtas de uma execução; temperatura, escalonamento e pequenas tarefas diagnósticas concorrentes podem afetar taxas. Não é promessa de ganho idêntico em produção. Não foi utilizada GPU.','',f"A otimização Python reutiliza ocupação estática, candidatos de reset e distâncias dos raios; retirou transformações identidade redundantes. Preservou exatamente estados, observações e recompensas em {optimization['equivalent_transitions']} transições. A implementação C mantém o mesmo passo de amostragem, máscara e ruído, sem aproximar raios nem usar fast-math/FMA. Preservou {native_validation['equivalent_transitions']} transições e 64 casos de fronteira. Mais forte: **os pesos finais PPO ficaram idênticos bit a bit** entre Python e nativo para 1, 2 e 4 ambientes, após as 4.096 transições de cada benchmark.",'','![Resultados](resultados.png)','','## Dois pilotos controlados','', 'Cada piloto recebeu 32.768 passos adicionais a partir do modelo parado `treino_2016_transferido_20261110_085342/final.zip`; pesos e otimizador de origem foram preservados. Ambos usaram quatro ambientes, uma seed de treino (42), o mesmo orçamento e rollout total de 512. O sampler inicial limita início–objetivo a 0,8–2 m de distância euclidiana no maior componente do disco. Isso não garante percurso geodésico curto: obstáculos podem exigir desvios. Nenhum nível avançou automaticamente.','', 'A: observação e recompensa originais. B: muda apenas o vetor local ao alvo, substituído por waypoint do A* no mapa conhecido, calculado com **pose estimada**; a política não recebe pose verdadeira. A recompensa continua usando chegada/progresso do objetivo final. A variante B exige esse mesmo módulo de waypoints em inferência e não é um substituto direto da política A.','', '| Método | Sucessos/100 | Colisões/100 | Timeouts/100 |','|---|---:|---:|---:|']
for s,t in zip(subjects,titles):
 r=results[s];lines.append(f"| {t} | {round(r['success']*100)} | {round(r['collision']*100)} | {round(r['timeout']*100)} |")
lines+=['','Esta avaliação usa a geometria/percepção v2 e não é diretamente comparável aos 25% das oito sementes no mapa SLAM antigo. O primeiro conjunto usa seeds 3300000000–3300000099. Hash de mapa+pose inicial+alvo coincide entre os seis métodos. Para o planejador com pose verdadeira, a pose privilegiada é somente uma referência diagnóstica, não um sensor disponível no robô. O controle e o mapa são os mesmos no diagnóstico com pose estimada.','', 'Diferenças pareadas de sucesso em relação ao modelo anterior (bootstrap 10.000 reamostragens dos episódios e McNemar exato):','']
for s in ['baseline','waypoints']:
 r=paired[s];lines.append(f"- {s}: {100*r['change']:+.1f} pp; IC95% [{100*r['ci95'][0]:.1f}, {100*r['ci95'][1]:.1f}] pp; p={r['p']:.3f}.")
lines+=['','Esses intervalos quantificam incerteza no conjunto de cenários, não variabilidade entre seeds de treinamento. Só uma seed de treino foi usada nos pilotos; não há demonstração de superioridade robusta entre algoritmos. Nenhum modelo foi selecionado pela melhor avaliação intermediária.','', '## Gate de dificuldade','', '| Modelo | Sucesso em 100 metas até 2 m | Colisões | Libera próximo estágio? |','|---|---:|---:|---|']
for s,t in zip(subjects[:3],titles[:3]):
 r=load(RUN/f'eval_gate_{s}/summary.json');lines.append(f"| {t} | {round(r['success']*100)} | {round(r['collision']*100)} | Não |")
lines+=['','Gate pré-definido: pelo menos 90% de sucesso e zero colisões observadas em 100 cenários independentes. Seeds do gate: 3301000000–3301000099. Todos falharam; não houve promoção nem novo treino longo. Zero colisões em uma amostra futura tampouco provaria risco real zero.','', '## O que os diagnósticos mostram','', f"- Planejador com pose verdadeira: **{round(results['planner_oracle']['success']*100)}% de sucesso**, zero colisões. Sob as hipóteses de física e altura, os 100 objetivos desse conjunto são executáveis por esse controlador; não é validação de todas as estações nem do hardware.",f"- Mesmo planejador com pose estimada: **{round(results['planner_estimated']['success']*100)}%**, {round(results['planner_estimated']['collision']*100)} colisões e {round(results['planner_estimated']['timeout']*100)} timeouts. A localização degrada fortemente esse controlador.",f"- Política antiga recebendo pose verdadeira antes de cada decisão: **{round(results['policy_true_pose']['success']*100)}%**, contra 1% originalmente. Isso reduz o erro de pose, mas não resolve o comportamento aprendido. Não se pode atribuir a falha da política somente à localização.",'- A ajuda por waypoints, aplicada a essa política e com esse orçamento, não trouxe ganho de sucesso. Não foi adotada como correção comprovada. A mudança de semântica/escala do vetor de objetivo em uma rede já treinada é uma limitação; este piloto não prova que aprendizagem com waypoints seja inviável.', '', 'A separação de camadas revela um desafio de percepção: plataformas de 10 cm ficam abaixo do LiDAR assumido a 20 cm, embora causem colisão. Um sistema de navegação precisa de mapa/localização ou sensor real apropriado. Não foi falsificado o scan para tornar obstáculos baixos visíveis. As alturas do LiDAR e do corpo continuam estimadas; nenhum ensaio no robô foi feito.','', '## Geometria e aproximações','',f"Foram obtidas **{services['accessible']}/{services['total']} aproximações** com footprint completo e retângulos de 0,80 m de largura, sem mover objetos nem mudar alturas. A busca considera deslocamento ao longo da face e 0,72 m de profundidade, que comporta o comprimento do robô e margens; o regulamento não foi interpretado como exigindo um quadrado de 0,80 m. O círculo passou a usar tangentes de aproximação, em vez de rejeitar todos os pequenos segmentos da sua discretização.",'','O verificador antigo também subtraía uma diagonal completa de célula no clearance. Uma grade de distância 4× mais fina, com limite conservador de meia diagonal da célula fina, removeu falsos bloqueios sem encolher paredes. As novas aproximações têm conexão no espaço de configuração discretizado, intersectado com clearance conservador >0,40 m. É validação discretizada, não certificado contínuo de SE(2), nem verificação de alcance do manipulador.','', 'Candidata: `experimentos_v2_20261110/layout_service_candidate.yaml`; imagem: `experimentos_v2_20261110/service_regions_resolved.png`. As camadas físicas/LiDAR copiadas são idênticas às originais; o layout ativo não foi substituído. A extração nativa do PDF e a calibração das alturas continuam pendentes.','', '## Cobertura do amostrador — problema encontrado e candidata','', f"O amostrador antigo usa apenas o maior dos {coverage['safe_components']} componentes do disco conservador: {coverage['largest_safe_cells']} de {coverage['all_safe_cells']} centros seguros, **{coverage['sampled_fraction_of_safe_centers']*100:.1f}%**. Isso não é porcentagem da área física: são células permitidas para o centro do disco. Ele exclui passagens que o retângulo atravessa orientado.",'',f"Foi criada uma candidata com {sampler['main_state_count']:,} estados do maior componente de SE(2), 24 orientações e conexões conservadoras de rotação. Em {sampler['resets']} resets, {sampler['starts_outside_old_largest_component']} inícios ficaram fora do componente antigo; as {sampler['collision_queries']} consultas de colisão para início e alvo passaram. A nova candidata conserva geometria, física e camadas. O planejador antigo por disco é explicitamente rejeitado nessa configuração; ele não pode ser usado silenciosamente para orientar tarefas mais amplas.",'','![Cobertura](cobertura.png)','','Avaliação adicional com 100 cenários do amostrador orientado, seeds 3401000000–3401000099:','', '| Modelo | Sucessos | Colisões | Timeouts |','|---|---:|---:|---:|']
for s,t in [('reference','Anterior'),('baseline','Piloto direto')]:
 r=wide[s];lines.append(f"| {t} | {round(r['success']*100)} | {round(r['collision']*100)} | {round(r['timeout']*100)} |")
lines+=['','A dupla usa os mesmos hashes de cenários entre si, mas esse conjunto tem distribuição diferente dos primeiros 100; não se comparam taxas entre conjuntos como se fossem o mesmo teste. Não foi realizado novo treinamento com o amostrador orientado.','', '## Próximo ciclo fundamentado','', '1. Usar a configuração de execução nativa com dois ambientes para economizar tempo. Manter os pilotos existentes como referências, sem promover um vencedor sem evidência.','2. Validar localização corrigida por sensores/mapa com dados reais. O salto 33%→100% do controlador de referência ao corrigir a pose torna isso uma prioridade mensurável.','3. Para aprender controle/navegação, testar imitação do planejador/controlador com entradas disponíveis no robô, depois PPO residual. O alvo intermediário isolado no modelo antigo não bastou. É proposta para próximo experimento, não implementação já validada.','4. Definir estágios por complexidade da rota geodésica e visibilidade, começando com trajetórias livres, em vez de apenas distância euclidiana. Exigir gate de desempenho e testar em seeds separadas.','5. Antes de expandir missões, integrar planejamento compatível com footprint orientado, validar todas as frentes e confirmar dimensões/alturas. Não voltar a deformar a arena para acomodar o amostrador.','', '## Artefatos e preservação','', f'Foram realizadas **1.100 avaliações de episódios**, reutilizando três baterias de 100 cenários para comparações controladas (não são 1.100 cenários independentes). Dois pilotos de 32.768 passos e seis benchmarks de 4.096 passos: 90.112 transições adicionais de aprendizado em execuções separadas. Todos terminaram; nenhum treinamento longo foi iniciado. Os {len(before)} arquivos protegidos foram novamente conferidos por SHA-256 e permaneceram idênticos. Modelos anteriores e logs não foram sobrescritos.','', 'Código e testes: `experimentos_v2_20261110/`; resultados, pesos e episódios: esta pasta. `analysis.json`, `by_distance.json`, `scenario_manifest.json`, `native_end_to_end_equivalence.json`, `recommended_configuration.json` e hashes acompanham o relatório. Os campos de sucesso/colisão são da física, não da pose estimada.']
(RUN/'RELATORIO.md').write_text('\n'.join(lines)+'\n')
print(json.dumps(dict(run=str(RUN),recommended_envs=recommend['n_envs'],gain_percent=(ratio-1)*100,coverage=wide),indent=2))
